#include <bits/stdc++.h>

#define FOR(i, n) for (int i = 0; i < (n); ++i)
#define REV(i, n) for (int i = (n) - 1; i >= 0; --i)

using namespace std;
using LL = long long;

struct MinCostFlow {
  struct Edge {
    int to;
    LL capacity;
    LL cost;
    int rev;
  };

  vector<vector<Edge>> graph;

  MinCostFlow(int n) : graph(n) {}

  void addEdge(int u, int v, LL cap, LL w) {
    int u_rev = graph[u].size();
    int v_rev = graph[v].size();
    graph[u].push_back({v, cap, w, v_rev});
    graph[v].push_back({u, 0, -w, u_rev});
  }

  LL minCostMaxFlow(int s, int t, LL flow_needed) {
    LL total_cost = 0;
    int n = graph.size();
    vector<LL> dist(n);
    vector<LL> potential(n);
    vector<int> parent(n), parent_edge(n);
    const LL INF = 1e18;
    while (flow_needed > 0) {
      fill(dist.begin(), dist.end(), INF);
      dist[s] = 0;
      priority_queue<pair<LL, int>> pq;
      pq.emplace(0, s);
      while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        d = -d;
        if (dist[u] < d) continue;
        for (int i = 0; i < (int)graph[u].size(); ++i) {
          auto &e = graph[u][i];
          if (e.capacity > 0 && dist[e.to] > dist[u] + e.cost + potential[u] - potential[e.to]) {
            dist[e.to] = dist[u] + e.cost + potential[u] - potential[e.to];
            parent[e.to] = u;
            parent_edge[e.to] = i;
            pq.emplace(-dist[e.to], e.to);
          }
        }
      }
      if (dist[t] == INF) return -1;
      for (int i = 0; i < n; ++i) potential[i] += dist[i];
      LL add_flow = flow_needed;
      for (int v = t; v != s; v = parent[v]) {
        add_flow = min(add_flow, graph[parent[v]][parent_edge[v]].capacity);
      }
      flow_needed -= add_flow;
      total_cost += add_flow * potential[t];
      for (int v = t; v != s; v = parent[v]) {
        auto &e = graph[parent[v]][parent_edge[v]];
        e.capacity -= add_flow;
        graph[v][e.rev].capacity += add_flow;
      }
    }
    return total_cost;
  }
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  LL N, M, K, C, D;
  cin >> N >> M >> K >> C >> D;
  vector<int> A(K);
  FOR(i, K) cin >> A[i], A[i]--;
  vector<int> us(M), vs(M);
  FOR(i, M) {
    cin >> us[i] >> vs[i];
    us[i]--;
    vs[i]--;
  }
  MinCostFlow mcf(N * 101 + 2);
  int s = N * 101;
  int t = s + 1;
  FOR(i, K) {
    mcf.addEdge(s, A[i], 1, 0);
  }
  for (int i = 0; i <= 100; ++i) {
    mcf.addEdge(N * i, t, K, C * i);
  }
  for (int i = 0; i < 100; ++i) {
    for (int j = 0; j < N; ++j) {
      mcf.addEdge(i * N + j, (i + 1) * N + j, K, 0);
    }
    for (int j = 0; j < M; ++j) {
      for (int k = 1; k <= K; ++k) {
        mcf.addEdge(N * i + us[j], N * (i + 1) + vs[j], 1, (2 * k - 1) * D);
        mcf.addEdge(N * i + vs[j], N * (i + 1) + us[j], 1, (2 * k - 1) * D);
      }
    }
  }
  cout << mcf.minCostMaxFlow(s, t, K) << '\n';
}
